static class Table {
    final String name;
    final List<Column>columns;
    final int key;
    List<List<Object>>rows = new ArrayList<>();
    Table(String n, List<Column>c, int key) {
        name = n;
        columns = c;
        this.key = key;
    }
    int column(String n) {
        for (int i = 0; i<columns.size(); i++) if (columns.get(i).name.equals(n)) return i;
        return -1;
    }
}
record Entry(String name, Table table, int offset) {
}
static class Scope {
    final List<Entry>entries = new ArrayList<>();
    int width;
    void add(String n, Table t) {
        if (entries.stream().anyMatch(e -> e.name.equals(n))) throw error("duplicate table name "+n);
        entries.add(new Entry(n, t, width));
        width += t.columns.size();
    }
    String resolve(Expr ref) {
        List<Map.Entry<Integer, String>>found = new ArrayList<>();
        boolean seen = false;
        for (Entry e:entries) if (ref.table == null || e.name.equals(ref.table)) {
            seen = true;
            int i = e.table.column(ref.column);
            if (i >= 0) found.add(Map.entry(e.offset+i, e.table.columns.get(i).type));
        }
        if (ref.table != null && !seen) throw error("unknown table "+ref.table);
        if (found.isEmpty()) throw error("unknown column "+ref.text);
        if (found.size()>1) throw error("ambiguous column "+ref.column);
        ref.index = found.get(0).getKey();
        return found.get(0).getValue();
    }
}
static boolean compatible(String a, String b) {
    return a.equals(b) || a.equals("NULL") || b.equals("NULL");
}
static void require(String a, String b, String op) {
    if (!compatible(a, b)) throw error("type mismatch for "+op);
}
static String check(Expr e, Scope s) {
    return check(e, s, false, null, false);
}
static String check(Expr e, Scope s, boolean allow, List<Integer>grouped, boolean inside) {
    if (e.kind.equals("literal")) return e.value == null?"NULL":e.value instanceof Long?"INT":"TEXT";
    if (e.kind.equals("ref")) {
        String type = s.resolve(e);
        if (grouped != null && !inside && !grouped.contains(e.index)) throw error("column "+e.text+" is not grouped");
        return type;
    }
    if (e.kind.equals("aggregate")) {
        if (!allow || inside) throw error("misuse of aggregate "+e.op);
static void condition(Expr e, Scope s, String name) {
    condition(e, s, name, false, null);
}
static void condition(Expr e, Scope s, String name, boolean allow, List<Integer>grouped) {
    if (e != null) require(check(e, s, allow, grouped, false), "INT", name);
}
static boolean truth(Object v) {
    return v != null && (Long) v != 0;
}
static Object evaluate(Expr e, List<Object>row) {
    return evaluate(e, row, null);
}
static Object evaluate(Expr e, List<Object>row, List<List<Object>>group) {
    if (e.kind.equals("literal")) return e.value;
    if (e.kind.equals("ref")) return row.get(e.index);
static boolean satisfies(Expr e, List<Object>row, List<List<Object>>group) {
    return e == null || truth(evaluate(e, row, group));
}
static String count(int n) {
    return n+(n == 1?" row":" rows");
}
static String written(Object v) {
    return v == null?"NULL":v.toString();
}
